@app.cell
def _(Path, os):
    NOTEBOOK = "01"
    WORK_ROOT = Path(os.environ.get("ABSGD_WORK_ROOT", str(Path.home() / "absgd-iwildcam"))).expanduser()
    os.environ["ABSGD_WORK_ROOT"] = str(WORK_ROOT)

    # Runs in queue order (method, seed). absgd = E1, erm = E2, cb = E3. ABSGD seeds first so the headline
    # replication finishes earliest; ablations after.
    QUEUE = [("absgd", 2)]  # this account trains E1 seed 2 only; seeds 0 and 1 run on the main account
    ABSGD_LAMBDA = 1.1  # --lamda in the authors' command

    # The authors' recipe (wilds-competition/ReadME.md command + main.py defaults). Change only in a forked notebook.
    HPARAMS = {
        "model": "resnet50",
        "pretrained_url": "https://github.com/rwightman/pytorch-image-models/releases/download/v0.1-rsb-weights/resnet50_a1_0-14fe96d1.pth",
        "epochs": 36, "batch_size": 16, "lr": 4e-5, "weight_decay": 0.0,
        "sc_gamma": 0.5,          # StepLR x0.5 at epoch 18
        "cb_shots": 5, "beta": 0.9999, "truncate_weight": 10,   # class-balanced weights from epoch 5, counts capped at 10
        "drogamma": 0.9, "ab_alpha": 1.0, "lamda_warm": 200.0,  # ABSGD moving average; lambda 200 (= plain mean) in 1st half
        "crop": 448, "randaug_n": 2,
    }
    # From 00_setup_absgd.py's benchmark on the RTX PRO 6000 (20 CPUs): 8 loader workers are fastest (582 img/s), and
    # the GPU (288 img/s at batch 16, ~10 GB) is the bottleneck, ~6 h per run alone. Two runs at once share the GPU:
    # no worse in total, and faster if one batch-16 run leaves the card underused. Compare min/epoch in the status table.
    NUM_WORKERS = 8      # DataLoader workers per run (the authors' value; this machine was not benchmarked)
    MAX_PARALLEL = 1     # one run on this account
    EVAL_FIXED_NORM = True   # E4: also score every epoch with ImageNet-normalised eval inputs (one extra forward pass)
    SAVE_LOGITS = True       # per-epoch eval logits (float16) to HF: needed for the authors' ensembling in 02_results_absgd.py
    CLEANUP_CHECKPOINTS = True   # delete last-checkpoint/ from the model repo once a run is done (best model.pt stays)
    MAX_ATTEMPTS = 3

    # Gate: a short run of the first queue entry goes first; if it fails, nothing else starts.
    SMOKE_FIRST = True
    SMOKE = {"epochs": 2, "max_train_steps": 100, "max_eval_items": 500}  # quick check of this machine; epoch 1 exercises ABSGD + class weights

    STAGES = {"launch": True}
    FORCE = set()            # e.g. {"train@resnet50-erm-s0"}: retrain a finished run from scratch (applied when the queue starts)
    RESTART_QUEUE = False    # True: stop the running queue runner and start one with this config (training processes keep running). Set back to False afterwards
    return (ABSGD_LAMBDA, CLEANUP_CHECKPOINTS, EVAL_FIXED_NORM, FORCE, HPARAMS, MAX_ATTEMPTS, MAX_PARALLEL, NOTEBOOK, NUM_WORKERS,
            QUEUE, RESTART_QUEUE, SAVE_LOGITS, SMOKE, SMOKE_FIRST, STAGES, WORK_ROOT)


